from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _ledger(data, sequence_first=False, discounted_tax=False):
    rounding = data["rounding"]
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        revision = event.get("revision", 0)
        key = ((sequence, revision, pos) if sequence_first
               else (revision, pos))
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    def rounded(n, d):
        if rounding == "half_up":
            return (n + d // 2) // d
        return n // d

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        base = net if discounted_tax else raw
        tax = rounded(base * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    domains = {}
    for name in packages:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        domains[name] = [-1] + versions

    best = None
    assignment = {}

    def valid():
        installed = {name for name, version in assignment.items() if version != -1}
        for name, (low, high) in roots.items():
            if name not in installed or not low <= assignment[name] <= high:
                return False
        edges = {name: [] for name in installed}
        for name in installed:
            row = next(r for r in packages[name] if r["version"] == assignment[name])
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in installed or not dep["min"] <= assignment[target] <= dep["max"]:
                    return False
                edges[name].append(target)
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name not in installed:
                return False
            row = next(r for r in packages[name] if r["version"] == assignment[name])
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if not feature or feature in features:
                    stack.append(dep["name"])
        if reachable != installed:
            return False
        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges[name]:
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        return all(visit(name) for name in installed)

    def search(index):
        nonlocal best
        if index == len(names):
            if valid():
                vector = tuple(assignment[name] for name in names)
                if best is None or vector > best[0]:
                    best = (vector, {n: v for n, v in assignment.items() if v != -1})
            return
        name = names[index]
        for version in domains[name]:
            assignment[name] = version
            search(index + 1)
        del assignment[name]

    search(0)
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best[1]}


def _quota_intervals(data):
    import itertools

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in itertools.combinations(
            [job for job in jobs if job["id"] not in blocked], k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        ok = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                ok = False
                break
        if not ok:
            continue
        selected = tuple(sorted(ids))
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_state = (dest, mask | bit_for.get(dest, 0), left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _ledger(data),
    "component_02": lambda data: _ledger(data, sequence_first=True),
    "component_03": lambda data: _ledger(data, discounted_tax=True),
    "component_04": lambda data: _ledger(data, sequence_first=True, discounted_tax=True),
    "component_05": lambda data: _ledger(data),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
